UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites arithmétiques et géométriques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites arithmétiques (raison $r$ par addition, $u_n = u_0 + nr$) et géométriques (raison $q$ par multiplication, $u_n = u_0 q^n$). Sommes : Gauss pour les arithmétiques, $u_0 (1-q^{n+1})/(1-q)$ pour les géométriques.","exercices":[{"number":1,"title_fr":"Identification arithmétique","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 2$ et $u_{n+1} = u_n + 4$.","questions":[{"number":1,"stem_fr":"Justifier que $(u_n)$ est arithmétique et donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"Par définition : $(u_n)$ arithmétique $\\iff u_{n+1} - u_n = r$ constant. Ici $u_{n+1} - u_n = (u_n + 4) - u_n = 4$."},{"text_fr":"La différence est **constante et vaut 4**, indépendante de $n$. Donc $(u_n)$ est arithmétique de **raison $r = 4$**."}],"final_answer_fr":"$r = 4$"}},{"number":2,"stem_fr":"Donner $u_n$ en fonction de $n$ puis calculer $u_{20}$.","points":2,"solution":{"steps":[{"text_fr":"**Terme général arithmétique** : $u_n = u_0 + nr = 2 + 4n$."},{"text_fr":"$u_{20} = 2 + 4 \\times 20 = 82$.","tip_fr":"L''expression explicite $u_n = u_0 + nr$ permet d''accéder à n''importe quel terme sans énumérer les précédents."}],"final_answer_fr":"$u_n = 2 + 4n$, $u_{20} = 82$"}},{"number":3,"stem_fr":"Calculer la somme $S = u_0 + u_1 + \\dots + u_{20}$ (21 termes).","points":1,"solution":{"steps":[{"text_fr":"**Formule de Gauss** : $S = \\text{(nb termes)} \\times \\dfrac{\\text{premier} + \\text{dernier}}{2}$."},{"text_fr":"$S = 21 \\times (u_0 + u_{20})/2 = 21 \\times (2 + 82)/2 = 21 \\times 42 = 882$."}],"final_answer_fr":"$S = 882$"}}]},{"number":2,"title_fr":"Identification géométrique","points":5,"preamble_fr":"Soit $(v_n)$ définie par $v_0 = 3$ et $v_{n+1} = 2 v_n$.","questions":[{"number":1,"stem_fr":"Montrer que $(v_n)$ est géométrique et préciser sa raison.","points":2,"solution":{"steps":[{"text_fr":"$(v_n)$ géométrique $\\iff v_{n+1}/v_n = q$ constant (avec $v_n \\ne 0$). Ici $v_{n+1}/v_n = 2 v_n / v_n = 2$."},{"text_fr":"Donc $(v_n)$ est géométrique de **raison $q = 2$**.","mistake_fr":"Ne pas confondre arithmétique (différence constante) et géométrique (rapport constant) — le doublement, triplement, etc. est géométrique."}],"final_answer_fr":"$q = 2$"}},{"number":2,"stem_fr":"Donner $v_n$ en fonction de $n$ et calculer $v_{10}$.","points":1,"solution":{"steps":[{"text_fr":"**Terme général géométrique** : $v_n = v_0 q^n = 3 \\cdot 2^n$."},{"text_fr":"$v_{10} = 3 \\times 1024 = 3072$."}],"final_answer_fr":"$v_n = 3 \\cdot 2^n$, $v_{10} = 3072$"}},{"number":3,"stem_fr":"Calculer $S = v_0 + v_1 + \\dots + v_{10}$.","points":2,"solution":{"steps":[{"text_fr":"**Formule géométrique** : $S = v_0 \\dfrac{1 - q^{n+1}}{1 - q}$ pour $n+1$ termes ($q \\ne 1$)."},{"text_fr":"Ici 11 termes ($v_0$ à $v_{10}$), $v_0 = 3$, $q = 2$. $S = 3 \\cdot \\dfrac{1 - 2^{11}}{1 - 2} = 3 \\cdot \\dfrac{1 - 2048}{-1} = 3 \\times 2047 = 6141$."}],"final_answer_fr":"$S = 6141$"}}]},{"number":3,"title_fr":"Sens de variation et limites","points":5,"preamble_fr":"Étudier le comportement à l''infini selon la nature et les paramètres de la suite.","questions":[{"number":1,"stem_fr":"Suites arithmétiques.","points":2,"subparts":[{"letter":"a","stem_fr":"Donner le sens de variation d''une suite arithmétique selon le signe de $r$.","points":1,"solution":{"steps":[{"text_fr":"$u_{n+1} - u_n = r$. Donc : $r > 0$ → strictement croissante ; $r < 0$ → strictement décroissante ; $r = 0$ → constante."}]}},{"letter":"b","stem_fr":"Donner $\\lim u_n$ selon le signe de $r$.","points":1,"solution":{"steps":[{"text_fr":"$r > 0$ : $u_n \\to +\\infty$. $r < 0$ : $u_n \\to -\\infty$. $r = 0$ : suite constante, limite $= u_0$."}],"final_answer_fr":"Limite $= \\pm\\infty$ sauf si $r = 0$"}}]},{"number":2,"stem_fr":"Suites géométriques ($u_0 > 0$).","points":3,"subparts":[{"letter":"a","stem_fr":"Sens de variation selon $q$.","points":1,"solution":{"steps":[{"text_fr":"$u_{n+1} - u_n = u_n(q - 1)$. Avec $u_0 > 0$ et $q > 0$ : $q > 1$ → croissante, $0 < q < 1$ → décroissante."},{"text_fr":"Si $q < 0$, les termes alternent de signe — pas de monotonie."}]}},{"letter":"b","stem_fr":"Limites selon $q$.","points":2,"solution":{"steps":[{"text_fr":"**$q > 1$** : $q^n \\to +\\infty$ donc $u_n \\to +\\infty$."},{"text_fr":"**$q = 1$** : suite constante, limite $= u_0$."},{"text_fr":"**$|q| < 1$** : $q^n \\to 0$ donc $u_n \\to 0$."},{"text_fr":"**$q \\le -1$** : la suite oscille (pas de limite).","tip_fr":"Mémo : pour les géométriques, seule la position de $q$ par rapport à $\\pm 1$ détermine le comportement asymptotique."}]}}]}]},{"number":4,"title_fr":"Application — capital à intérêts composés","points":5,"preamble_fr":"Un capital $C_0 = 5000\\,\\text{DH}$ est placé à 4% d''intérêts composés annuels. Soit $C_n$ le capital après $n$ années.","questions":[{"number":1,"stem_fr":"Exprimer $C_{n+1}$ en fonction de $C_n$ et identifier la nature de la suite.","points":2,"solution":{"steps":[{"text_fr":"Chaque année, le capital est multiplié par $1{,}04$ (capital initial + 4% d''intérêt). Donc $C_{n+1} = 1{,}04 \\cdot C_n$."},{"text_fr":"$(C_n)$ est **géométrique** de raison $q = 1{,}04$ et de premier terme $C_0 = 5000$."}],"final_answer_fr":"Géométrique, $q = 1{,}04$"}},{"number":2,"stem_fr":"Calculer $C_{10}$ et $C_{20}$.","points":2,"solution":{"steps":[{"text_fr":"$C_n = 5000 \\times 1{,}04^n$. $1{,}04^{10} \\approx 1{,}4802$ → $C_{10} \\approx 7401\\,\\text{DH}$."},{"text_fr":"$1{,}04^{20} \\approx 2{,}1911$ → $C_{20} \\approx 10\\,956\\,\\text{DH}$.","tip_fr":"Règle de 72 : à 4%, doublement en environ $72/4 = 18$ ans. Cohérent avec $C_{20} \\approx 2 C_0$."}],"final_answer_fr":"$C_{10} \\approx 7401$ DH, $C_{20} \\approx 10\\,956$ DH"}},{"number":3,"stem_fr":"Au bout de combien d''années le capital aura-t-il triplé ?","points":1,"solution":{"steps":[{"text_fr":"Résoudre $1{,}04^n = 3 \\iff n \\ln(1{,}04) = \\ln 3 \\iff n = \\ln 3 / \\ln(1{,}04) \\approx 1{,}0986 / 0{,}0392 \\approx 28\\,\\text{ans}$."}],"final_answer_fr":"$n \\approx 28$ ans"}}]}]}'::jsonb WHERE code = 'pc_arithmetic_geom_seq';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Convergence des suites","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Convergence, théorème des gendarmes, théorème de la limite monotone, opérations sur les limites.","exercices":[{"number":1,"title_fr":"Limites usuelles","points":5,"preamble_fr":"Calculer les limites suivantes.","questions":[{"number":1,"stem_fr":"$\\lim_{n \\to \\infty} 1/n$, $\\lim 1/n^2$, $\\lim 1/\\sqrt{n}$.","points":2,"solution":{"steps":[{"text_fr":"**Règle générale** : pour tout $\\alpha > 0$, $\\lim_{n \\to \\infty} 1/n^\\alpha = 0$ (avec $\\sqrt n = n^{1/2}$)."},{"text_fr":"Les trois limites valent donc **0**. Plus $\\alpha$ est grand, plus la décroissance est rapide."}],"final_answer_fr":"Toutes valent 0"}},{"number":2,"stem_fr":"$\\lim_{n \\to \\infty} \\dfrac{3n^2 + n + 1}{n^2 - 2}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $\\infty/\\infty$ : on **factorise le terme dominant** (ici $n^2$) en haut et en bas."},{"text_fr":"$\\dfrac{3n^2 + n + 1}{n^2 - 2} = \\dfrac{n^2(3 + 1/n + 1/n^2)}{n^2(1 - 2/n^2)} = \\dfrac{3 + 1/n + 1/n^2}{1 - 2/n^2} \\to \\dfrac{3}{1} = 3$."},{"text_fr":"**Règle** : pour un quotient de polynômes de même degré, la limite est le rapport des coefficients dominants."}],"final_answer_fr":"$\\lim = 3$"}},{"number":3,"stem_fr":"$\\lim_{n \\to \\infty} \\sqrt{n+1} - \\sqrt{n}$.","points":1,"solution":{"steps":[{"text_fr":"Forme indéterminée $\\infty - \\infty$. **Astuce de la quantité conjuguée** : multiplier par $\\dfrac{\\sqrt{n+1} + \\sqrt{n}}{\\sqrt{n+1} + \\sqrt{n}}$."},{"text_fr":"$\\sqrt{n+1} - \\sqrt{n} = \\dfrac{(n+1) - n}{\\sqrt{n+1} + \\sqrt{n}} = \\dfrac{1}{\\sqrt{n+1} + \\sqrt{n}} \\to 0$.","mistake_fr":"Ne pas conclure que $\\sqrt{n+1} - \\sqrt{n} \\to \\infty - \\infty = 0$ : cette ''soustraction'' n''a pas de sens, il faut lever l''indétermination."}],"final_answer_fr":"$\\lim = 0$"}}]},{"number":2,"title_fr":"Théorème des gendarmes","points":5,"preamble_fr":"Soit $u_n = \\dfrac{\\cos(n)}{n}$ pour $n \\ge 1$.","questions":[{"number":1,"stem_fr":"Encadrer $u_n$.","points":2,"solution":{"steps":[{"text_fr":"Pour tout $n$, $-1 \\le \\cos(n) \\le 1$. Comme $n > 0$, on divise par $n$ sans changer le sens : $-1/n \\le \\cos(n)/n \\le 1/n$."}],"final_answer_fr":"$-1/n \\le u_n \\le 1/n$"}},{"number":2,"stem_fr":"En déduire $\\lim u_n$.","points":3,"solution":{"steps":[{"text_fr":"Les deux bornes $-1/n$ et $1/n$ tendent vers 0 quand $n \\to \\infty$."},{"text_fr":"Par le **théorème des gendarmes**, $u_n$ est encadrée par deux suites convergeant vers la même limite 0. Donc $\\lim u_n = 0$.","tip_fr":"$\\cos(n)$ n''a pas de limite (oscille entre -1 et 1), mais $\\cos(n)/n$ converge grâce à la décroissance dominante de $1/n$."}],"final_answer_fr":"$\\lim u_n = 0$"}}]},{"number":3,"title_fr":"Théorème de la limite monotone","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 1$ et $u_{n+1} = \\sqrt{2 + u_n}$.","questions":[{"number":1,"stem_fr":"Étude de $(u_n)$.","points":4,"subparts":[{"letter":"a","stem_fr":"Montrer par récurrence que $0 \\le u_n \\le 2$.","points":2,"solution":{"steps":[{"text_fr":"**Init** : $u_0 = 1 \\in [0, 2]$ ✓."},{"text_fr":"**Hérédité** : si $0 \\le u_n \\le 2$, alors $2 \\le 2 + u_n \\le 4$, donc $\\sqrt 2 \\le u_{n+1} \\le 2$. Comme $\\sqrt 2 \\approx 1{,}41 > 0$, on a bien $0 \\le u_{n+1} \\le 2$."}]}},{"letter":"b","stem_fr":"Montrer que $(u_n)$ est croissante.","points":1,"solution":{"steps":[{"text_fr":"Étude de signe : $u_{n+1}^2 - u_n^2 = (2 + u_n) - u_n^2 = -(u_n - 2)(u_n + 1)$. Sur $[0, 2]$, $(u_n - 2) \\le 0$ et $(u_n + 1) > 0$, donc $u_{n+1}^2 - u_n^2 \\ge 0$."},{"text_fr":"Comme $u_n, u_{n+1} \\ge 0$, ceci entraîne $u_{n+1} \\ge u_n$. La suite est croissante."}]}},{"letter":"c","stem_fr":"Conclure sur la convergence et calculer la limite.","points":1,"solution":{"steps":[{"text_fr":"($u_n$) est croissante et majorée par 2 → par le **théorème de la limite monotone**, elle converge vers une limite $L \\le 2$."},{"text_fr":"$L$ vérifie $L = \\sqrt{2 + L}$ (passage à la limite). Élever au carré : $L^2 = 2 + L \\iff L^2 - L - 2 = 0 \\iff (L-2)(L+1) = 0$, donc $L = 2$ (puisque $L \\ge 0$)."}],"final_answer_fr":"$L = 2$"}}]}]},{"number":4,"title_fr":"Opérations sur les limites","points":5,"preamble_fr":"Calculer ou justifier l''absence de limite pour les suites suivantes.","questions":[{"number":1,"stem_fr":"$u_n = (-1)^n$.","points":2,"solution":{"steps":[{"text_fr":"$u_n$ vaut alternativement $+1$ ($n$ pair) et $-1$ ($n$ impair). Elle prend deux valeurs distinctes à l''infini."},{"text_fr":"Donc $(u_n)$ **n''a pas de limite** (la suite des termes pairs converge vers 1, celle des impairs vers -1 — limites différentes → divergence)."}],"final_answer_fr":"Pas de limite"}},{"number":2,"stem_fr":"$v_n = n - n^2$.","points":1,"solution":{"steps":[{"text_fr":"Forme $\\infty - \\infty$. Factoriser : $v_n = n(1 - n) = -n(n - 1)$."},{"text_fr":"Quand $n \\to \\infty$, $n(n-1) \\to +\\infty$ donc $v_n \\to -\\infty$."}],"final_answer_fr":"$\\lim v_n = -\\infty$"}},{"number":3,"stem_fr":"$w_n = \\dfrac{(-1)^n}{n} + 3$.","points":2,"solution":{"steps":[{"text_fr":"$(-1)^n / n$ est encadrée par $-1/n$ et $1/n$, donc tend vers 0 (gendarmes)."},{"text_fr":"Par somme des limites : $\\lim w_n = 0 + 3 = 3$."}],"final_answer_fr":"$\\lim w_n = 3$"}}]}]}'::jsonb WHERE code = 'pc_seq_convergence';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites récurrentes","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites définies par $u_{n+1} = f(u_n)$, points fixes, suites arithmético-géométriques, convergence par monotonie + bornes.","exercices":[{"number":1,"title_fr":"Récurrence affine simple","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 0$ et $u_{n+1} = \\dfrac{u_n + 6}{2}$.","questions":[{"number":1,"stem_fr":"Calculer $u_1, u_2, u_3$ et conjecturer le comportement.","points":2,"solution":{"steps":[{"text_fr":"$u_1 = (0 + 6)/2 = 3$. $u_2 = (3 + 6)/2 = 4{,}5$. $u_3 = (4{,}5 + 6)/2 = 5{,}25$."},{"text_fr":"La suite semble **croître et se stabiliser autour de 6** : 0, 3, 4.5, 5.25, 5.625, ..."}],"final_answer_fr":"Conjecture : croissante, limite $\\approx 6$"}},{"number":2,"stem_fr":"Trouver le point fixe de $f(x) = (x+6)/2$ et le comparer à la conjecture.","points":2,"solution":{"steps":[{"text_fr":"**Point fixe** : $L = f(L) \\iff L = (L + 6)/2 \\iff 2L = L + 6 \\iff L = 6$. ✓ avec la conjecture."},{"text_fr":"Le point fixe est un **candidat-limite** ; pour conclure rigoureusement, il faut prouver la convergence (monotonie + bornes).","mistake_fr":"Trouver le point fixe ne prouve pas la convergence : certaines suites n''atteignent jamais leur point fixe (ex. $u_{n+1} = 2 u_n - 6$ avec $u_0 = 0$ diverge bien que 6 soit un point fixe)."}],"final_answer_fr":"$L = 6$"}},{"number":3,"stem_fr":"Montrer que $(u_n)$ est croissante et majorée par 6, puis conclure.","points":1,"solution":{"steps":[{"text_fr":"**Majoration** par récurrence : si $u_n \\le 6$, alors $u_{n+1} = (u_n + 6)/2 \\le (6 + 6)/2 = 6$. Init OK avec $u_0 = 0 \\le 6$."},{"text_fr":"**Croissance** : $u_{n+1} - u_n = (u_n + 6)/2 - u_n = (6 - u_n)/2 > 0$ tant que $u_n < 6$."},{"text_fr":"Croissante + majorée → converge vers le point fixe $L = 6$."}]}}]},{"number":2,"title_fr":"Récurrence non linéaire","points":5,"preamble_fr":"Soit $(u_n)$ telle que $u_0 = 1$ et $u_{n+1} = \\sqrt{3 u_n + 4}$.","questions":[{"number":1,"stem_fr":"Étude complète.","points":4,"subparts":[{"letter":"a","stem_fr":"Trouver le(s) point(s) fixe(s).","points":1,"solution":{"steps":[{"text_fr":"$L = \\sqrt{3L + 4} \\Rightarrow L^2 = 3L + 4 \\Rightarrow L^2 - 3L - 4 = 0$."},{"text_fr":"Discriminant : $9 + 16 = 25$. Racines : $L = (3 + 5)/2 = 4$ ou $L = (3 - 5)/2 = -1$. La racine carrée étant positive, $L \\ge 0$, donc $L = 4$."}],"final_answer_fr":"$L = 4$"}},{"letter":"b","stem_fr":"Montrer par récurrence que $1 \\le u_n \\le 4$.","points":2,"solution":{"steps":[{"text_fr":"Init : $u_0 = 1 \\in [1, 4]$ ✓."},{"text_fr":"Hérédité : si $1 \\le u_n \\le 4$, alors $7 \\le 3 u_n + 4 \\le 16$, donc $\\sqrt 7 \\le u_{n+1} \\le 4$. Comme $\\sqrt 7 \\approx 2{,}65 > 1$, on a bien $1 \\le u_{n+1} \\le 4$."}]}},{"letter":"c","stem_fr":"Conclure sur la convergence.","points":1,"solution":{"steps":[{"text_fr":"Étude de signe : $u_{n+1}^2 - u_n^2 = (3 u_n + 4) - u_n^2 = -(u_n - 4)(u_n + 1)$. Sur $[1, 4]$, $(u_n - 4) \\le 0$ et $(u_n + 1) > 0$ → $u_{n+1}^2 \\ge u_n^2$ → $u_{n+1} \\ge u_n$ (les termes étant positifs)."},{"text_fr":"Croissante + majorée par 4 → converge. La limite vérifie l''équation du point fixe → $L = 4$."}],"final_answer_fr":"$\\lim u_n = 4$"}}]},{"number":2,"stem_fr":"Combien d''itérations pour atteindre $|u_n - 4| < 10^{-3}$ ?","points":1,"solution":{"steps":[{"text_fr":"Calcul itératif : $u_0 = 1$ (err = 3), $u_1 = \\sqrt 7 \\approx 2{,}65$ (err ≈ 1.35), $u_2 \\approx \\sqrt{11{,}95} \\approx 3{,}46$ (err ≈ 0.54), $u_3 \\approx \\sqrt{14{,}37} \\approx 3{,}79$ (err ≈ 0.21), $u_4 \\approx 3{,}92$, $u_5 \\approx 3{,}97$, $u_6 \\approx 3{,}99$, $u_7 \\approx 3{,}996$ (err ≈ 4×10⁻³), $u_8 \\approx 3{,}998$ (err ≈ 1.5×10⁻³), $u_9\\approx 3{,}9994$ (err < 10⁻³)."},{"text_fr":"Donc dès $n = 9$, la précision est atteinte."}],"final_answer_fr":"$n \\approx 9$"}}]},{"number":3,"title_fr":"Suite arithmético-géométrique","points":5,"preamble_fr":"Soit $(u_n)$ avec $u_0 = 1$ et $u_{n+1} = 3 u_n - 4$.","questions":[{"number":1,"stem_fr":"Trouver le point fixe $\\ell$ de $f(x) = 3x - 4$.","points":1,"solution":{"steps":[{"text_fr":"$\\ell = 3 \\ell - 4 \\iff 2 \\ell = 4 \\iff \\ell = 2$."}],"final_answer_fr":"$\\ell = 2$"}},{"number":2,"stem_fr":"Poser $v_n = u_n - \\ell$. Montrer que $(v_n)$ est géométrique et donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"$v_{n+1} = u_{n+1} - 2 = (3 u_n - 4) - 2 = 3 u_n - 6 = 3(u_n - 2) = 3 v_n$."},{"text_fr":"Donc $(v_n)$ est **géométrique de raison $q = 3$**.","tip_fr":"**Astuce arithmético-géométrique** : pour $u_{n+1} = a u_n + b$ avec $a \\ne 1$, le changement de variable $v_n = u_n - \\ell$ (où $\\ell$ est le point fixe $\\ell = b/(1-a)$) rend la suite géométrique pure."}],"final_answer_fr":"Géométrique, $q = 3$"}},{"number":3,"stem_fr":"Déterminer l''expression explicite de $u_n$ et sa limite.","points":2,"solution":{"steps":[{"text_fr":"$v_0 = u_0 - 2 = -1$. Donc $v_n = v_0 q^n = -3^n$."},{"text_fr":"Et $u_n = v_n + 2 = 2 - 3^n$."},{"text_fr":"Vérification : $u_0 = 2 - 1 = 1$ ✓. $u_1 = 2 - 3 = -1$ ; formule $3(1) - 4 = -1$ ✓."},{"text_fr":"Quand $n \\to \\infty$, $3^n \\to +\\infty$ donc $u_n \\to -\\infty$. La suite **diverge** ; le point fixe 2 est **répulsif** ($|q| > 1$)."}],"final_answer_fr":"$u_n = 2 - 3^n$, $\\lim = -\\infty$"}}]},{"number":4,"title_fr":"Application — modèle démographique","points":5,"preamble_fr":"Dans une cuve de production, la population de bactéries triple chaque heure mais 200 bactéries sont prélevées pour analyse. À $t = 0$, on a 500 bactéries.","questions":[{"number":1,"stem_fr":"Modéliser la population $P_n$ après $n$ heures.","points":1,"solution":{"steps":[{"text_fr":"$P_0 = 500$. Chaque heure : triplement ($\\times 3$) puis prélèvement ($-200$). Donc $P_{n+1} = 3 P_n - 200$."}],"final_answer_fr":"$P_{n+1} = 3 P_n - 200$, $P_0 = 500$"}},{"number":2,"stem_fr":"Déterminer l''expression explicite $P_n$.","points":3,"solution":{"steps":[{"text_fr":"Point fixe : $\\ell = 3 \\ell - 200 \\iff 2\\ell = 200 \\iff \\ell = 100$."},{"text_fr":"Posons $Q_n = P_n - 100$. Alors $Q_{n+1} = P_{n+1} - 100 = 3 P_n - 200 - 100 = 3(P_n - 100) = 3 Q_n$."},{"text_fr":"$(Q_n)$ géométrique de raison 3, $Q_0 = 500 - 100 = 400$. Donc $Q_n = 400 \\cdot 3^n$ et **$P_n = 100 + 400 \\cdot 3^n$**."}],"final_answer_fr":"$P_n = 100 + 400 \\cdot 3^n$"}},{"number":3,"stem_fr":"Calculer $P_5$ et conclure sur le comportement à long terme.","points":1,"solution":{"steps":[{"text_fr":"$P_5 = 100 + 400 \\cdot 3^5 = 100 + 400 \\times 243 = 100 + 97\\,200 = 97\\,300$ bactéries."},{"text_fr":"Quand $n \\to \\infty$, $3^n \\to +\\infty$ donc $P_n \\to +\\infty$ : la population **explose exponentiellement** malgré les prélèvements, car la croissance interne ($\\times 3$) domine largement la décroissance externe ($-200$)."}],"final_answer_fr":"$P_5 = 97\\,300$, explose"}}]}]}'::jsonb WHERE code = 'pc_seq_recursive';

COMMIT;
